use vstd::prelude::*;

verus! {
    fn insert_before_each(arr: &Vec<i32>, elem: i32) -> (result: Vec<i32>)
        ensures
            result.len() == 2 * arr.len(),
            forall |k: nat| 0 <= k < arr.len() ==> 
                result[2 * k] == elem && result[2 * k + 1] == arr[k],
    {
        let mut result: Vec<i32> = Vec::new();
        let n = arr.len() as nat;

        // Loop to interleave the elements
        let mut i: nat = 0;
        while i < n
            invariant
                i <= n,
                result.len() == 2 * i,
                forall |k: nat| 0 <= k < i ==> 
                    result[2 * k] == elem && result[2 * k + 1] == arr[k],
            decreases n - i,
        {
            // Insert the element before the current element of arr
            result.push(elem);
            result.push(arr[i as usize]);
            i = i + 1;
        }

        // Handle the case when arr is empty
        if n == 0 {
            assert(result.len() == 0);
        }

        result
    }
}

